from collections import deque

def allow(timestamps, limit, window):
    """Return whether each call is allowed under a sliding-window limiter."""
    if limit <= 0:
        return [False] * len(timestamps)
    if window <= 0:
        raise ValueError("window must be positive")

    allowed_times = deque()
    result = []

    for t in timestamps:
        window_start = t - window + 1

        # Remove allowed calls that are outside the inclusive window.
        while allowed_times and allowed_times[0] < window_start:
            allowed_times.popleft()

        permitted = len(allowed_times) < limit
        result.append(permitted)

        # Rejected calls are not added to the window.
        if permitted:
            allowed_times.append(t)

    return result
```

The function runs in **O(n)** time and uses **O(limit)** auxiliary space, excluding the returned list. The input is not modified.

