from heapq import heappop, heappush


def shortest(edges, src, dst):
    """Return the minimum directed path weight from src to dst, or -1."""
    if src == dst:
        return 0

    # Build a local adjacency list without modifying edges.
    graph = {}
    for u, v, w in edges:
        graph.setdefault(u, []).append((v, w))

    best = {src: 0}
    heap = [(0, src)]  # (distance, node)

    while heap:
        distance, node = heappop(heap)

        # Ignore outdated heap entries.
        if distance != best[node]:
            continue

        if node == dst:
            return distance

        for neighbor, weight in graph.get(node, ()):
            candidate = distance + weight
            if neighbor not in best or candidate < best[neighbor]:
                best[neighbor] = candidate
                heappush(heap, (candidate, neighbor))

    return -1
```

This uses Dijkstra’s algorithm, which is valid because all edge weights are positive. The input list is only read, not modified.

